from html import escape as E

def M(tex,small=False): return '<div class="math'+(' small-math' if small else '')+'" data-math="'+E(tex,quote=True)+'"></div>'
def R(html,n=1):return f'<div data-r="{n}">{html}</div>'
def O(html,n):return f'<div data-only="{n}">{html}</div>'
def P(text,cl=''):return f'<p class="{cl}">{text}</p>'
def I(name,cl='',alt=None):return f'<img class="figure-image {cl}" src="figures/{name}" alt="{E(alt or name)}">'
def F(name,**opts):
    import json
    return f'<div class="figure" data-figure="{name}" data-options="{E(json.dumps(opts),quote=True)}"></div>'
def D(kind,controls='',compact=False):return f'<div class="interactive {"compact" if compact else ""}" data-kind="{kind}"><div class="plot"></div><div class="readout" aria-live="polite"></div><div class="controls">{controls}</div><div class="print-state"></div></div>'
def slider(name,title,lo,hi,value,step=.05):return f'<label>{title} <output data-value="{name}">{value}</output><input aria-label="{title}" data-param="{name}" type="range" min="{lo}" max="{hi}" step="{step}" value="{value}"></label>'
def btn(action,t):return f'<button data-action="{action}">{t}</button>'
def split(a,b,cl=''):return f'<div class="split {cl}"><div>{a}</div><div>{b}</div></div>'
SOURCE={'VAE':'https://arxiv.org/abs/1312.6114','GAN':'https://arxiv.org/abs/1406.2661','Flow':'https://arxiv.org/abs/1505.05770','MNIST':'https://yann.lecun.com/exdb/mnist/','Photo':'https://www.robots.ox.ac.uk/~vgg/data/pets/'}
def story():
    slides=[]
    def add(id,title,body,section,builds=1,idea='',provenance='ILLUSTRATIVE · authored teaching diagram',notes='',question='',answer='',source=None,appendix=False):
        slides.append(dict(id=id,title=title,body=body,section=section,builds=builds,idea=idea,provenance=provenance,notes=notes,question=question or title,answer=answer,source=SOURCE.get(source,source),appendix=appendix))
    S='00 · Why generate?'
    add('start','Generative Modelling I',P('From randomness to data','hero')+P('Distributions, priors, latent variables, VAEs and GANs','subtitle')+'<div class="cover-visual">'+F('pipeline',labels=['random z','learned map'],colors=['purple','teal'])+I('vae16-prior-draws.png',alt='Measured binary digit samples from VAE-16')+'</div>',S,idea='How can we learn what valid data looks like?',provenance='MEASURED · VAE-16 prior draws, seed 667 · ES667 · Nipun Batra',notes='Opening question: so far we have mostly produced labels, matches or next tokens. Today we ask how to make another valid object. The digits are actual samples from the small run supplied with this lecture; imperfections are expected.',answer='We learn a distribution over possible objects, then draw new samples.')
    add('recall','What have our models been doing?', '<div class="rows"><div><strong class="blue">IMAGE</strong><span>ViT → class</span></div><div><strong class="blue">TEXT</strong><span>encoder → intent</span></div><div><strong class="blue">IMAGE + TEXT</strong><span>CLIP → match score</span></div></div>'+R(M(r'x\longrightarrow y')+P('What if we want another valid image?','large')),S,2,notes='Invite three quick answers before revealing the new question. CLIP supplies a similarity score, not automatically a calibrated probability.',answer='These models predict something about a supplied input. Generating asks for a new input-like object.')
    add('another-digit','Could we make another handwritten digit?',split(P('Observed MNIST','label blue')+I('observed.png'),R(P('New draws from our learned model','label purple')+I('vae16-prior-draws.png'))),S,2,'New samples should resemble the data distribution.',provenance='OBSERVED DATA / MEASURED · thresholded MNIST / VAE-16 prior + Bernoulli draws',source='MNIST',notes='The left grid is the first 32 test digits after fixed binary thresholding. The right is an unselected fixed-seed draw from a trained VAE-16. No labels were used in training. Ask which aspects seem plausible and which fail.',answer='We want new draws with the structure and variability of the data, not simply copied labels.')
    add('distribution-question','What does it mean to learn a distribution?',D('sample-density',btn('toggle','Show / hide model density')),S,idea='Observed points are finite. The distribution describes possible points.',provenance='MEASURED FIT on ILLUSTRATIVE DATA · seeded eight-Gaussian cloud; learned EM density',notes='Introduce the recurring eight-mode ring. The observations are simulated from a known mixture; the contour overlay is an eight-component Gaussian mixture fitted by EM without component labels. It is a learned non-neural density. The fit is evaluated on its training cloud, not claimed as held-out generalization. This is a conceptual preview.',answer='Learn where probability mass belongs so new draws have the right structure and coverage.')
    S='01 · Distributions and sampling'
    add('discrete','If we sample 100 times, what might happen?',D('discrete',btn('ten','Draw 10')+btn('hundred','Draw 100')+btn('reset','Reset')),S,2,'Frequencies approach probabilities; they need not equal them.',provenance='ILLUSTRATIVE · seeded independent categorical draws · dashed lines = target proportions',notes='First ask for predictions with P(red)=.2, P(blue)=.5, P(green)=.3. Reveal the actual fixed-seed 100-draw histogram. Reset and use 10 draws to show fluctuation. Expected counts 20/50/30 are expectations, not guaranteed results.',answer='Usually near 20 red, 50 blue and 30 green, with random variation.')
    add('gaussian','What do μ and σ control?',D('gaussian',slider('mu','μ',-2,2,0)+slider('sigma','σ',.25,2,1)+btn('resample','Fresh draws'),True)+M(r'x\sim\mathcal N(\mu,\sigma^2)',True),S,idea='Move the centre. Change the spread.',provenance='ANALYTICAL / EXACT density · ILLUSTRATIVE random draws',notes='Move mean while keeping sigma fixed, then sigma while keeping mean fixed. The same standard noise is reused during parameter changes; Fresh draws changes it. Variance is sigma squared, not sigma.',answer='Mean translates the distribution; standard deviation sets its scale.')
    add('area','Is the height of this curve a probability?',F('density',mu=0,sig=1,opts={'point':True})+O(P('At exactly one real value: zero probability.','large coral'),0)+O(M(r'P(-1\leq X\leq1)=\int_{-1}^{1}p(x)\,dx\approx0.683'),1),S,2,'Probability is area under a density.',provenance='ANALYTICAL / EXACT · standard Gaussian, rounded interval probability',notes='Reveal the interval shading. Density has units inverse to x and can exceed one. For a continuous variable the probability at a single exact value is zero. The curve is not a histogram of individual real numbers.',answer='No. Integrate density over an interval to get probability.')
    add('multimodal','Can one Gaussian describe these eight groups?',D('mixture',btn('single','One Gaussian')+btn('mixture','Mixture')),S,idea='One bell can put probability where there is little data.',provenance='ILLUSTRATIVE samples · analytical mixture / moment-matched single Gaussian contours',notes='Begin with a single Gaussian matching population first and second moments. Toggle to the known mixture. Both views use the identical 280 points and axes. Eight clusters, not eight digit labels.',answer='A single Gaussian cannot represent separated high-density modes with low-density gaps.')
    add('recipe','Could a simple recipe already generate data?',F('pipeline',labels=['choose k','draw offset','return x'],colors=['purple','purple','blue'])+M(r'k\sim\operatorname{Categorical}(\pi),\qquad x\mid k\sim\mathcal N(m_k,s^2I)',True)+P('Choose one of the eight centres, then add a small Gaussian offset.','hint'),S,idea='A generative model need not be a neural network.',provenance='ANALYTICAL / EXACT · equal weights 1/8; radius 2.4; component σ = 0.23',notes='Use component k=0 with centre (2.4,0), and offset (0.1,-0.2), giving x=(2.5,-0.2), orally. Component labels are latent variables too. This is a real sampling recipe.',answer='Yes. A mixture is already a probability model with a precise sampling algorithm.')
    add('learn-density','Which parameters explain our observations?',D('fit',slider('mu','model μ',-2,2,0),True)+R(M(r'\hat\theta=\arg\max_\theta\sum_{i=1}^N\log p_\theta(x_i)')),S,2,'Raise the density at observed values, under a normalized model.',provenance='ANALYTICAL / EXACT · 1D worked data: −0.5, 0.5, 1.5; fixed σ = 1',notes='Vary mu and watch summed log density. The maximum occurs at sample mean .5 for this fixed-variance Gaussian. These are densities, not probabilities of exact real numbers. Generalization still matters; fitting observations does not guarantee the true distribution.',answer='Choose parameters giving high likelihood to the observations. Here the best mean is .5.')
    add('two-abilities','Can we sample it? Can we evaluate its density?',split(M(r'x_{\mathrm{new}}\sim p_\theta')+P('Sampling','large purple')+P('Draw another object.','hint'),M(r'p_\theta(x)\;\text{or}\;\log p_\theta(x)')+P('Density evaluation','large amber')+P('Score an observed object, if tractable.','hint')),S,idea='Different model families give different access to these operations.',provenance='CONCEPTUAL · sampling and tractable normalized density are separate abilities',notes='A generator can transform random samples without an easy normalized density formula. A VAE decoder likelihood is conditional; its marginal p(x) integrates over z and is usually intractable. This prepares the later GAN/flow comparison.',answer='No. Having a sampler does not imply tractable normalized density evaluation.')
    S='02 · We already know one'
    add('language','Our decoder-only language model was generative', '<div class="tokens"><span class="token">The</span><span>→</span><span class="token">The dog</span><span>→</span><span class="token">The dog ran</span></div>'+R(M(r'p(x_1,\ldots,x_T)=\prod_{t=1}^T p(x_t\mid x_{<t})')),S,2,'Sample a token, append it, repeat.',provenance='ILLUSTRATIVE token sequence · exact autoregressive factorization',notes='Recall the Indian-name generator and next-token exercises without reteaching attention. At each step a categorical distribution supplies the next draw. The displayed words are an authored sequence, not a recorded model output.',answer='It defines a joint distribution through conditional distributions and samples sequentially.')
    add('pixels','Could we do the same for image pixels?',F('pixels')+M(r'p(x)=\prod_{j=1}^{784}p(x_j\mid x_{<j})'),S,idea='Choose an order, then predict each part from earlier parts.',provenance='ILLUSTRATIVE · schematic binary pixel order; not a trained image model',notes='The grid is schematic and small enough to read. A flattened binary MNIST image has 784 variables. Other models use image tokens rather than pixels. The factorization is exact; tractability depends on conditional models.',answer='Yes. Autoregressive image models use pixels or tokens in a chosen order.')
    add('whole-object','Must every part wait for the previous part?',F('sequential-vs-latent'),S,idea='Could one learned transformation turn randomness into a whole object?',notes='Contrast sequential sampling with a latent generator. This is a question about generation structure, not a blanket speed ranking. Training an autoregressive model can still parallelize across observed sequence positions.',answer='Not necessarily. A latent generator can map a random vector to all output coordinates in one pass.')
    S='03 · Latent variables'
    add('sevens','What makes two handwritten 7s different?',I('sevens.png','strip')+'<div class="legend"><span>slant</span><span>thickness</span><span>height</span><span>shape</span></div>'+P('These motivate hidden factors. They are not promised learned axes.','hint'),S,provenance='OBSERVED DATA · first eight held-out MNIST 7s after binary thresholding',notes='Ask students to point to visible differences. We use the word latent for unobserved factors or variables. Standard VAEs do not guarantee independent semantic dimensions or disentanglement.',answer='Several hidden factors could vary; learned latent coordinates need not correspond one-to-one to those factors.')
    add('prior','Where will our randomness come from?',D('prior',btn('sample','Draw a new z'))+R(M(r'z\sim p(z),\qquad p(z)=\mathcal N(0,I)')),S,2,'The prior is chosen before observing this particular example x.',provenance='ILLUSTRATIVE standard Gaussian draws · chosen latent prior',notes='The unit Gaussian is a modeling assumption here, not something an ordinary AE automatically learns. Show one purple point. The prior is not the data distribution and is not conditioned on the particular x.',answer='We choose a simple, sampleable prior over latent vectors, often a standard multivariate Gaussian.')
    add('latent-generator','What should a neural generator do with z?',F('pipeline',labels=['z','decoder','x'],colors=['purple','teal','blue'])+M(r'z\sim p(z),\qquad x\sim p_\theta(x\mid z)'),S,idea='Turn a simple latent draw into a distribution over data.',notes='A probabilistic decoder outputs parameters of p(x|z); drawing x can introduce additional randomness. In our Bernoulli example the image of probabilities is a decoder mean, not itself a binary sample. A deterministic GAN generator instead directly outputs x.',answer='It maps a latent draw to output values or to parameters of an observation distribution.')
    add('which-z','During training we see x. Which z explains it?',F('pipeline',labels=['observed x','which z?','decoder'],colors=['blue','purple','teal'])+P('The hidden cause was not supplied with the training example.','large'),S,notes='Let the missing z feel like a practical problem. We can invent a network going from x back toward a code. Do not display a VAE graph yet.',answer='We need an inference mechanism; an encoder is one way to learn it.')
    add('autoencoder','Could an encoder find a useful code?',F('pipeline',labels=['x','encoder','z','decoder','x̂'],colors=['blue','teal','purple','teal','blue'])+R(I('ae2-recon.png','strip')+P('Top: observed digits · bottom: decoder means','caption')),S,2,'An ordinary autoencoder learns to reconstruct its input.',provenance='MEASURED · AE-2 reconstruction means on first held-out examples',notes='This AE uses BCE on binary data and a 2D deterministic code. It has no KL or prior matching penalty. The displayed reconstructions are limited by two-dimensional capacity.',answer='Yes. Optimize an encoder and decoder for reconstruction; that does not yet solve prior sampling.')
    add('ae-sampling','Will a random Gaussian code decode well?',D('ae',btn('ae','Ordinary AE')+btn('vae','VAE'))+R(P('The AE never agreed to organize its codes like this prior.','takeaway')),S,2,provenance='MEASURED latent means · amber 2σ prior circle; same coordinate scale for AE and VAE',notes='Compare the actual AE and VAE code scatter with the chosen standard Gaussian reference. Empty regions and mismatch are observed geometry here, not a theorem that all AEs fail. The browser can switch the measured recorded model. Prior samples are in the notes/experiment outputs.',answer='Not necessarily. Reconstruction alone imposes no standard-Gaussian organization on encoded points.')
    S='04 · Variational autoencoder'
    add('encoder-distribution','What if the encoder predicts a distribution?',O(F('pipeline',labels=['x','encoder','one vector z'],colors=['blue','teal','purple']),0)+O(D('posterior',slider('mu','μ₁',-1.5,1.5,1)+slider('sigma','σ₁',.2,1.5,.6)),1)+R(M(r'\mu_\phi(x),\ \log\sigma_\phi^2(x)\in\mathbb R^d,\qquad q_\phi(z\mid x)=\mathcal N\!\left(\mu_\phi(x),\operatorname{diag}(\sigma_\phi^2(x))\right)',True)),S,2,provenance='ILLUSTRATIVE posterior ellipse · d=2 or d=16 in measured runs',source='VAE',notes='The encoder outputs 2d numbers: d means and d log variances, not a sampled z directly. For batch B these arrays are B×d. Exponentiating half log variance gives positive standard deviation. Each x has its own q.',answer='Predict parameters of a conditional approximate posterior, then sample a latent vector from it.')
    add('three-objects','Which distribution are we talking about?', '<div class="trio"><div><h3 class="amber">Prior</h3>'+M(r'p(z)')+P('Simple latent draws before seeing x.')+'</div><div><h3 class="purple">Approximate posterior</h3>'+M(r'q_\phi(z\mid x)')+P('An encoder’s distribution for this x.')+'</div><div><h3 class="teal">Decoder likelihood</h3>'+M(r'p_\theta(x\mid z)')+P('Possible data given a latent z.')+'</div></div>',S,source='VAE',provenance='CONCEPTUAL · three distinct distributions',notes='Ask which object depends on x and which has learned theta. q approximates the generally intractable true posterior p_theta(z|x); do not call q the true posterior. The decoder likelihood is not the marginal data density.',answer='The prior supplies z, q infers z from x, and the decoder models x given z.')
    add('opaque-sample','How will a reconstruction gradient reach the encoder?',F('reparam',stage=0)+P('An opaque stochastic node leaves the gradient estimator unspecified.','takeaway'),S,source='VAE',notes='Avoid claiming sampling is mathematically impossible to differentiate. Several gradient estimators exist. We want a low-variance pathwise estimator for this location-scale Gaussian family.',answer='We must specify how the random draw depends on encoder parameters and choose a gradient estimator.')
    add('independent-noise','Could the random draw be independent of the encoder?',F('reparam',stage=1)+O(M(r'\epsilon\sim\mathcal N(0,I)'),0)+O(M(r'z=\mu+\sigma\odot\epsilon'),1),S,2,source='VAE',notes='Introduce epsilon first. Hold that draw fixed while differentiating the deterministic computation. The operation is elementwise for a diagonal Gaussian. On the second build reveal add and z in the graph.',answer='Yes. Sample standard noise independently, then scale and shift it using the encoder outputs.')
    add('same-distribution','Why does scale-and-shift give the right distribution?',D('location-scale',slider('mu','μ',-2,2,2)+slider('sigma','σ',.25,2,.5))+O(M(r'\epsilon\sim\mathcal N(0,1)'),0)+O(M(r'\mu+\sigma\epsilon\sim\mathcal N(\mu,\sigma^2)'),1),S,2,provenance='ANALYTICAL / EXACT identity · same illustrative standard-noise draws',source='VAE',notes='Use the same points to show a changed location and spread. E[z]=mu and Var[z]=sigma squared because E[epsilon]=0 and Var[epsilon]=1. This establishes equality in distribution, not equal numerical values for independent draws.',answer='Affine transformation preserves Gaussianity and gives mean mu and variance sigma squared.')
    add('computation-graph','Can you draw the actual computation graph?',F('reparam',stage=2)+R(P('Only the independent ε node introduces randomness.','takeaway')),S,2,source='VAE',notes='First show multiply and add. Then connect z to decoder and reconstruction loss. Ask students to redraw this before looking at backward arrows. The decoder loss depends on the observed x target, described in the notes.',answer='Noise multiplies sigma; add mu; pass z through the decoder; compare its output distribution to the observed x.')
    add('sample-arithmetic','What latent value do these numbers produce?',M(r'\mu=2,\quad \sigma=0.5,\quad \epsilon=-0.8')+O(F('pipeline',labels=['−0.8','× 0.5','+ 2','z = ?'],colors=['purple','amber','amber','purple']),0)+R(M(r'z=2+0.5(-0.8)'),1)+R(M(r'z=1.6'),2),S,3,'Same computation. One fixed noise draw.',provenance='ANALYTICAL / EXACT · hand-chosen worked values',notes='Pause before revealing the product and sum. Ask whether drawing epsilon again would yield the same z. It would generally not. The parameters stay fixed but the sample varies.',answer='1.6. The distribution is N(2, .25), but this particular sample is 1.6.')
    add('gradient-arithmetic','Where do reconstruction gradients go?',F('reparam',stage=3,grad=True)+O(M(r'\frac{\partial L_{\rm recon}}{\partial z}=3'),0)+O(M(r'\frac{\partial z}{\partial\mu}=1,\qquad\frac{\partial z}{\partial\sigma}=\epsilon=-0.8'),1)+O(M(r'\frac{\partial L_{\rm recon}}{\partial\mu}=3,\qquad\frac{\partial L_{\rm recon}}{\partial\sigma}=-2.4'),2),S,3,provenance='ANALYTICAL / EXACT · reconstruction-path gradients only; complete loss also has KL',source='VAE',notes='Apply the chain rule one edge at a time. Stop at the partial derivatives before showing answers. The KL contributes additional gradients in the full objective. No gradient is needed with respect to the random-number generator.',answer='The pathwise reconstruction derivatives are 3 for mu and -2.4 for sigma, holding epsilon fixed.')
    add('code','What does the log-variance parameterization change?',split('<pre class="code">mu, logvar = encoder(x)\nstd = exp(0.5 * logvar)\neps = randn_like(std)\nz = mu + std * eps</pre>',F('code-path'))+R(M(r'\frac{\partial z}{\partial\log\sigma^2}=\tfrac12\sigma\epsilon=-0.2\quad\Rightarrow\quad\frac{\partial L_{\rm recon}}{\partial\log\sigma^2}=-0.6',True)),S,2,provenance='ANALYTICAL / EXACT · previous μ, σ, ε and upstream gradient; elementwise code',source='VAE',notes='The scalar derivative -0.2 comes from .5 times .5 times -.8. Multiplying upstream gradient 3 gives -.6. This is still the reconstruction path only. Practical code uses log variance for unconstrained outputs and positive scales.',answer='The chain rule adds a factor one-half sigma when differentiating with respect to log variance.')
    S='05 · Why two loss terms?'
    add('two-requirements','Why not optimize reconstruction alone?',F('pipeline',labels=['explain x','AND','match prior'],colors=['blue','gray','amber'])+P('A decoder trained on one latent region may be poor on draws from another.','large'),S,idea='We need a reconstruction objective and a principled link to the prior.',source='VAE',notes='Return to the measured AE mismatch. We are not adding a penalty merely for attractive scatter plots: the KL follows from the variational bound on marginal log likelihood.',answer='Reconstruction alone does not connect the inferred latent distributions to the prior used for generation.')
    add('elbo','Why does the VAE loss have two parts?',M(r'\mathcal L_{\rm VAE}=\underbrace{-\mathbb E_{q_\phi(z\mid x)}[\log p_\theta(x\mid z)]}_{\text{explain the observed data}}')+R(M(r'\qquad+\underbrace{D_{\rm KL}\!\left(q_\phi(z\mid x)\,\|\,p(z)\right)}_{\text{compare each approximate posterior to the prior}}')),S,2,'Minimize the negative evidence lower bound (negative ELBO).',provenance='ANALYTICAL / EXACT · standard β=1 VAE objective per example',source='VAE',notes='First discuss expected negative log likelihood. Then reveal KL. The reconstruction expectation uses posterior samples during training; KL is analytical for a diagonal Gaussian against a unit Gaussian. The optional backup gives the bound identity. Minimizing this loss maximizes a lower bound, not generally exact log p(x).',answer='One term explains the observation; the other arises from variational inference and compares q(z|x) to p(z).')
    add('likelihood','What does “reconstruction loss” actually mean?', '<div class="rows"><div><strong class="teal">Gaussian output</strong><span>Fixed variance → squared-error-like loss</span></div><div><strong class="teal">Bernoulli output</strong><span>Binary observations → binary cross entropy</span></div></div>'+M(r'-\log p_\theta(x\mid z)\;\text{depends on the observation model}',True),S,idea='Our experiment uses binary MNIST and Bernoulli likelihood.',provenance='ANALYTICAL / EXACT · fixed threshold x > 127 applied to uint8 pixels',source='VAE',notes='The reconstruction term is not universally MSE. A Gaussian with fixed observation variance produces scaled squared error plus a constant. We threshold MNIST so BCE is a literal Bernoulli log likelihood, not a claim about original grayscale values.',answer='It is negative log likelihood under the chosen decoder observation model.')
    add('kl-interactive','How far is this posterior from the prior?',D('kl',slider('mu','posterior μ',-2,2,1)+slider('sigma','posterior σ',.25,2,.5)),S,2,provenance='ANALYTICAL / EXACT · purple q(z|x), amber p(z)=N(0,1)',source='VAE',notes='Move mean toward zero and sigma toward one. Curve overlap is an intuition; the displayed KL uses the exact formula, not a visual area distance. KL is asymmetric and measured in nats. The second build reveals its value.',answer='For these Gaussian distributions KL reaches zero exactly when mean is zero and standard deviation is one.')
    add('kl-arithmetic','Can we calculate one KL by hand?',M(r'D_{\rm KL}=\tfrac12\left(\mu^2+\sigma^2-\log\sigma^2-1\right)')+M(r'\mu=1,\qquad \sigma=0.5')+R(M(r'D_{\rm KL}=\tfrac12(1+0.25-\log0.25-1)\approx0.818\ \text{nats}')+P('At μ = 0 and σ = 1, KL = 0.','hint')),S,2,provenance='ANALYTICAL / EXACT · natural logarithm; rounded to three decimals',source='VAE',notes='Do not show .818 until the class has substituted sigma squared=.25. The d-dimensional diagonal formula sums these scalar contributions. KL does not assert that every class is a perfect Gaussian cluster.',answer='About .818 nats; zero at the unit Gaussian prior.')
    add('full-vae','Now we can assemble the VAE',F('full-vae')+P('The complete objective combines reconstruction and KL to the prior.','takeaway'),S,source='VAE',notes='This is the first full VAE architecture. The encoder produces mu and log variance, epsilon supplies independent noise, z feeds the decoder, and two loss paths supply gradients. q for each example is compared to p; this is not a class-cluster constraint.',answer='Every component solves a previously introduced problem: inference, differentiable sampling, observation modeling, and prior compatibility.')
    add('train-generate','What stays when we only want a new sample?',O(F('pipeline',labels=['x','encoder','sample z','decoder','x̂'],colors=['blue','teal','purple','teal','blue'])+P('TRAINING · infer a distribution from this x','label blue'),0)+O(F('pipeline',labels=['prior z','decoder','new x'],colors=['purple','teal','blue'])+P('GENERATION · no encoder is needed','label purple'),1),S,2,source='VAE',notes='At generation time sample z from the prior. The decoder produces Bernoulli probabilities; sample each output pixel if a binary image is needed. A reconstruction instead conditions its inferred latent on x.',answer='The decoder and prior suffice for generation. The encoder is used for inference and reconstruction.')
    add('measured-models','What did the small models actually learn?',split(P('Latent dimension 2','label purple')+I('vae2-recon.png','strip')+I('vae2-prior16-means.png','strip'),P('Latent dimension 16','label teal')+I('vae16-recon.png','strip')+I('vae16-prior16-means.png','strip'))+P('Upper: input / reconstruction means · lower: prior-decoded means','caption'),S,provenance='MEASURED · 60,000 train / 10,000 test · 15 epochs · seed 667 · unselected examples',source='MNIST',notes='Use at most 45 seconds here. Greater latent capacity changes this run’s quality; this is not a universal benchmark. All panels are decoder probability means. Actual binary draws appeared in the opening. Held-out BCE/KL and exact architecture are in the backup and metrics manifest.',answer='The 2D model is useful for seeing geometry; the 16D model has more capacity but still makes imperfect outputs.')
    decoder='<div class="interactive" data-kind="decoder"><div class="decoder-wrap"><div><div class="decoder-grid" role="application" tabindex="0" aria-label="Latent plane: click or use arrow keys"><img src="figures/vae2-grid.png" alt="Measured VAE-2 decoded latent grid from −3 to 3"><span class="cross"></span></div><p class="caption">z₁: −3 → 3 · z₂: 3 → −3</p></div><div><canvas class="decoder-output" width="28" height="28" aria-label="Decoded digit probabilities"></canvas><p class="readout" aria-live="polite"></p></div><div><p>Choose a point.<br>Decode it with the saved model.</p><div class="controls">'+btn('fallback','Use recorded fallback')+'</div><p class="caption decoder-status"></p></div></div></div>'
    add('latent-plane','What lives at this point in latent space?',decoder,S,provenance='MEASURED · VAE-2 decoder weights; fallback is nearest recorded 25×25 grid point',notes='Click two separated points and then the region between them. The live browser executes the saved decoder, not image interpolation. Arrow keys move .1 per coordinate. The fallback snaps to an actual recorded point and reports that coordinate; it does not pretend to run inference.',answer='A latent point specifies a decoder probability image. Nearby points can change the output smoothly, without guaranteed semantic axes.')
    add('paths-and-curves','What changes along a latent path?',O(I('vae16-interpolation.png','strip')+M(r'z(t)=(1-t)\mu(x_a)+t\mu(x_b),\qquad 0\leq t\leq1')+P('Nine equal steps between the first two test encodings.','caption'),0)+O(I('training-curves.svg','tall'),1),S,2,provenance='MEASURED · VAE-16 posterior-mean interpolation; training curves for VAE-2 and VAE-16',notes='First show interpolation between posterior means for the first two test examples. These are decoder means. Then show both training terms in separate axes with their own units. A falling reconstruction term alone is not the whole objective. These are training curves, not held-out learning curves.',answer='The decoder changes along a continuous latent path; training balances reconstruction and KL terms.')
    S='06 · Learning through a critic'
    add('another-signal','Must we train with that particular objective?',F('gan',stage=0)+P('What if another model could learn to judge realism?','large'),S,idea='Keep the generator. Change the training signal.',source='GAN',notes='The VAE used a probability model and a variational objective. GANs provide an alternative training signal. Introduce only the generator initially; no full game diagram yet.',answer='No. A learned discriminator can supply adversarial feedback.')
    add('discriminator','How could generated points get feedback?',F('gan',stage=1)+O(P('Mix observed data and generated samples.','large'),0)+O(P('Train D to distinguish the two sources.','large teal'),1),S,2,source='GAN',notes='The first view introduces real and fake inputs, the second emphasizes learning the discriminator. The score is useful for the adversarial objective; do not call it calibrated truth or general realism probability.',answer='Train a discriminator on the source labels of real and generated examples.')
    add('train-discriminator','What learns during the discriminator step?',F('gan',mode='D',stage=1)+M(r'L_D=-\mathbb E_{x\sim p_{\rm data}}\log D(x)-\mathbb E_{z\sim p(z)}\log\!\left(1-D(G(z))\right)',True),S,source='GAN',notes='Detach generated samples or run G without recording its gradient for the D step. Update D only. A numerical intuition: for one real score .8 and one fake score .2, the equally summed negative log terms total about .446, though batching conventions vary.',answer='Only D parameters update. Fake examples are treated as fixed inputs for this step.')
    add('train-generator','Can fixed discriminator weights still pass gradients?',F('gan',mode='G',stage=1)+O(P('Freeze D parameters; keep the path from its input to its score.','takeaway'),0)+O(M(r'L_G=-\mathbb E_{z\sim p(z)}\log D(G(z))')+P('Common non-saturating generator objective','caption'),1),S,2,source='GAN',notes='Do not wrap D(G(z)) in no_grad during the G step. Its parameters can have requires_grad false while operations still track dependence on G output. This loss differs from minimizing log(1-D(G(z))) in the classical minimax formulation. Backup contains that reference.',answer='Yes. Fixed parameter values still define a differentiable function of the input.')
    add('alternate','How do we train both networks?',D('gan',btn('D','Discriminator step')+btn('G','Generator step')),S,idea='Alternate which parameters are updated.',source='GAN',notes='Use the two buttons once each. The diagram is a teaching simulation, not a recorded GAN run. There is no guaranteed monotonic global progress from alternating gradient updates.',answer='Update D with G outputs detached; then update G using gradients through a fixed D.')
    add('coverage','If samples look plausible, have we succeeded?',D('collapse',slider('modes','generated modes',1,8,3,1))+R(P('Sample quality and distribution coverage are different questions.','takeaway')),S,2,provenance='ILLUSTRATIVE mode collapse · constructed three-mode sampler; not a GAN training result',source='GAN',notes='The blue points are the same seeded eight-mode dataset. Purple points are deliberately restricted to three modes to isolate the coverage issue. The optional measured GAN run is not presented. Labeling this constructed comparison is essential.',answer='No. A generator can make plausible points while missing most modes.')
